var e=`Child & Adolescent Therapy | Michelle Barratt Psychology`,t=`Child and adolescent therapy is available in Brisbane and online across Australia through Michelle Barratt Psychology. Our experienced psychologists support c`,n=`<!--$--><section class="bg-gradient-to-br from-plum to-rose text-white"><div class="mx-auto max-w-7xl px-5 py-14 md:py-20"><div><nav aria-label="Breadcrumb" class="mb-6"><ol class="flex flex-wrap items-center gap-2 text-[12px] uppercase tracking-[0.14em] text-white/75"><li><a class="hover:text-white" href="/">Home</a></li><li aria-hidden="true"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3 w-3"><path d="m9 18 6-6-6-6"></path></svg></li><li><a class="hover:text-white active" href="/therapy-services" data-status="active" aria-current="page">Therapy Services</a></li><li aria-hidden="true"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3 w-3"><path d="m9 18 6-6-6-6"></path></svg></li><li class="text-white" aria-current="page">Child &amp; Adolescent Therapy</li></ol></nav><p class="text-[12px] font-semibold uppercase tracking-[0.2em] text-white/85 mb-3">Children &amp; Adolescents</p><h1 class="text-white text-[32px] md:text-[44px] font-semibold leading-[1.08] max-w-3xl">Child and Adolescent Therapy</h1><div class="h-[3px] w-16 bg-sun my-5" aria-hidden="true"></div><div class="max-w-2xl text-[16px] md:text-[17px] text-white/95 space-y-3"><p>Child and adolescent therapy is available in Brisbane and online across Australia through Michelle Barratt Psychology. Our experienced psychologists support children, teenagers, and families navigating emotional, behavioural, social, and developmental challenges.</p><p>Evidence-based, age-appropriate therapy helps young people build resilience, strengthen emotional wellbeing, improve relationships, and develop the skills needed to thrive at home, at school, and beyond.</p></div><div class="mt-6 flex flex-wrap gap-3"><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 bg-white text-plum hover:bg-blush " href="/contact">Contact Us</a><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 border border-white/70 text-white hover:bg-white/10 " href="/practitioners">See Practitioners</a></div></div></div></section><section class="bg-soft !py-0"><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="py-14 md:py-16"><img src="https://michellebarrattpsychology.com.au/wp-content/uploads/2023/03/pexels-andrea-piacquadio-3807738-min.jpg" alt="Pexels Andrea Piacquadio 3807738 Min" class="w-full aspect-[16/9] max-h-[520px] object-cover rounded border border-lilac"/></div></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Early support for children and teenagers</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Child and adolescent therapy supports young people through anxiety, low mood, behavioural challenges, school difficulties, and developmental concerns. Early, appropriate intervention reduces long-term impact and helps children and teens build coping skills, emotional literacy, and stronger relationships at home and at school.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Michelle Barratt Psychology (MBP) provides in-person therapy across Brisbane and flexible online therapy for children and teenagers Australia-wide, making care easy to access at any age.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">How does MBP support access to Child and Teenage Therapy?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Michelle Barratt Psychology &amp; Administrative Services (MBP) provides a calm, clinically informed administrative entry point for families seeking care from Brisbane psychologists and allied health practitioners .</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">We manage sensitive communications, coordinate referrals, and streamline intake so clinicians can focus on assessment and therapy while parents receive clear, timely guidance.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">What support does MBP provide?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><div class="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 my-8"><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Clinically Informed Intake</h3><p class="text-[15px] leading-relaxed text-ink/85">Sensitive intake processes that help identify the most appropriate support pathway for children, adolescents, and families.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Family-Focused Coordination</h3><p class="text-[15px] leading-relaxed text-ink/85">Support for parents and caregivers navigating referrals, appointments, and treatment planning.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Age-Appropriate Care</h3><p class="text-[15px] leading-relaxed text-ink/85">Connection with practitioners experienced in working with children, adolescents, and family systems.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Coordinated Support</h3><p class="text-[15px] leading-relaxed text-ink/85">Liaison with schools, health providers, and other professionals where appropriate and consented.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Practical referral support</h3><p class="text-[15px] leading-relaxed text-ink/85">Assistance with referrals, Medicare paperwork, and administrative requirements.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Flexible Access</h3><p class="text-[15px] leading-relaxed text-ink/85">In-person Brisbane appointments and telehealth options available across Australia.</p></div></div></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">How do I get started?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">If you are seeking a respectful and professionally managed pathway to treatment, please complete your details on our Contact Form &amp;gt;</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">We will respond within 24 to 48 hours and help you find a Brisbane psychologist or allied health practitioner that best suits your needs.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">You may also view our Practitioner Page and select the clinician of your choice.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">If in crisis, please call 000.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Contact Us on the Form Below</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><h3 class="text-2xl font-semibold mt-8 mb-3">Important safety note</h3><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">If you are in immediate danger, experiencing severe distress, or having thoughts of harming yourself, contact emergency services or a crisis service right away. If you are concerned but not in immediate danger, please mention this when you contact us so we can prioritise an appropriate, timely response.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Learn More About Child &amp; Teenage Support</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Supporting Children, Teenagers, and Families</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Every child and teenager experiences challenges differently. Some struggle with managing emotions, behaviour, friendships, family relationships, school pressures, or major life changes. Others experience anxiety, low mood, social difficulties, or challenges with self-esteem and confidence.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Therapy gives children and adolescents a safe, supportive environment to develop healthy coping skills, improve communication, strengthen emotional regulation, and build resilience. Treatment is tailored to each child&#x27;s developmental stage and individual circumstances, with parents and caregivers actively involved where appropriate.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Supporting Your Child Through Challenges</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Parenting can be rewarding, but it can also be challenging when a child is struggling emotionally or behaviourally. Parents often report feeling uncertain about how to respond to conflict, emotional outbursts, school difficulties, behavioural concerns, or communication breakdowns.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Therapy can help parents better understand their child&#x27;s needs while providing practical strategies to strengthen relationships, improve communication, establish healthy boundaries, and create a supportive home environment.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Understanding the Teenage Years</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Adolescence is a time of rapid emotional, social, and psychological development. Teenagers are navigating increasing independence, identity formation, friendships, academic demands, social media influences, and family expectations.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">These changes can sometimes lead to conflict, emotional distress, anxiety, low mood, risk-taking behaviours, or difficulties communicating with parents. Therapy provides a supportive space for teenagers to explore challenges, develop coping skills, and build confidence while supporting healthier family relationships.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Understanding Toddler Behaviour and Tantrums</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Tantrums and emotional outbursts are a normal part of early childhood development as young children learn to understand and express their emotions. While occasional tantrums are expected, frequent or intense behavioural challenges can be stressful for both children and parents.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Professional support can help families better understand developmental needs, emotional regulation, communication patterns, and practical parenting strategies that promote positive behaviour and healthy emotional development.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">At Michelle Barratt Psychology , our psychologists take the time to understand each family&#x27;s situation before developing a support plan. Every treatment approach is built around your specific needs and goals, whether you&#x27;re starting therapy for the first time or continuing a journey already underway.</p><figure class="my-9"><img src="https://michellebarrattpsychology.com.au/wp-content/uploads/2026/05/38882.jpg" alt="38882" loading="lazy" class="w-full max-w-4xl aspect-[3/2] object-cover rounded border border-lilac"/></figure><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Every child, teenager, and family faces challenges from time to time. Professional support can help young people build resilience, improve emotional wellbeing, and develop healthy coping strategies w hile providing families with practical tools to navigate difficulties together. Contact Michelle Barratt Psychology to learn more about the support available for your child or adolescent.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Helping Families Thrive Together</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">When a child or teenager is struggling, the impact is often felt throughout the entire family. Therapy can support parents, caregivers, and siblings by improving communication, strengthening relationships, and developing practical strategies that support the well-being of the whole family.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Common areas of support include:</p><div class="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 my-8"><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">1 Parent-Child Communication</h3><p class="text-[15px] leading-relaxed text-ink/85">Supporting families to strengthen communication, improve understanding, and build healthier relationships between parents, caregivers, and young people.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">2 Managing Conflict</h3><p class="text-[15px] leading-relaxed text-ink/85">Providing practical strategies to address behavioural challenges, reduce family conflict, and create a more positive home environment.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">3 Emotional Regulation</h3><p class="text-[15px] leading-relaxed text-ink/85">Helping children, teenagers, and families develop skills to better understand, manage, and respond to strong emotions.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">5 Family Relationships</h3><p class="text-[15px] leading-relaxed text-ink/85">Strengthening family connections by promoting trust, cooperation, healthy boundaries, and supportive interactions.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">6 School and Social Support</h3><p class="text-[15px] leading-relaxed text-ink/85">Addressing challenges related to school, friendships, peer relationships, social confidence, and everyday functioning.</p></div></div></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">ADHD Therapy</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">We understand that kids often forget things—they might leave their hat at school, forget their homework, or act on impulse and say things without thinking, especially when they&#x27;re tired and a bit fidgety.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Types of ADHD Medications</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">https://www.understood.org/en/learning-attention-issues/treatments-approaches/medications/types-of-adhd-medications</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">However, kids with ADHD, particularly the Hyperactive Type, usually:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Have a hard time staying still,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Fidget constantly,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Don&#x27;t seem to listen,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Struggle to follow instructions, no matter how clearly you explain,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Sometimes say things that aren&#x27;t appropriate,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Act impulsively and are hard to manage,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Can&#x27;t seem to sit long enough to finish tasks,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Seem unable to concentrate for long periods,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Lose self-esteem because they can&#x27;t focus on what they need to do, leading to a lack of interest,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Become irritable and too tired to concentrate when it&#x27;s most needed.</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Unfortunately, these kids are often labelled as troublemakers or seen as lazy or undisciplined. But what we don&#x27;t realise is that they might have ADHD/ADD (Attention Deficit Hyperactivity Disorder) and need proper professional support.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Onset</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">ADHD usually shows up in early childhood. If you think your child might have some of these characteristics, talking to your GP about it is wise. They can recommend a professional to give your child further advice and determine if they have ADHD.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">What to do</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">If your child has ADHD/ADD, a psychologist specialising in ADHD Therapy can offer the support and skills your child needs to thrive in their education, maintain strong family bonds, and keep up friendships they make at school.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Impact of ADHD</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">For a child with ADHD, trying to learn at school can be very tough when they&#x27;re struggling to concentrate. They might start to feel frustrated and down about their progress and their inability to complete tasks.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Their behaviour can also make it hard for them to make and keep friends, which can lead to other issues like low self-esteem and the loss of the chance to build social skills as they grow.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Michelle Barratt encourages every parent to seek an assessment if their child shows any symptoms of ADHD. She would love to connect with your child to support and guide them through their learning journey. Michelle&#x27;s ADHD Therapy is focused on the child/client, ensuring they feel safe and understood. Her skills allow her to work with the child and their family, providing practical strategies at every opportunity.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Her main goal is to offer the best strategies to help the child adjust and hopefully overcome the symptoms of ADHD so they can lead every day, healthy lives.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">As a child psychologist Brisbane. Michelle has worked with children from the ages of 3 years to young adults. Her service aims to provide a therapeutic environment where clients feel trusted, supported, and safe. She focuses on ensuring that individuals, children, adolescents, and families receive the best psychological support through counselling or therapy for any trauma or adjustment issues.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">ADHD Therapy sessions will include practices that give clients the best chance to understand their outcomes and achieve their goals regardless of their situation, issues, or age. These sessions will use psychological assessments and interventions based on evidence-based practice for treatment planning.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Teenage Anxiety and Depression</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Teens can go through both anxiety and depression, two common mental health issues that often happen together. It&#x27;s essential for parents, caregivers, and teachers to understand how teenage anxiety and depression are linked, recognise their signs, and offer the proper support.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Teenage Anxiety: Teenage anxiety is when a teen feels excessive worry, fear, or unease that affects their life. Teens with anxiety might constantly worry, feel restless, have trouble focusing, have sleep problems, and even get physical symptoms like headaches or stomach aches. Anxiety can bring in the way of a teen&#x27;s daily life, social interactions, and overall happiness.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Teenage Depression: Teenage depression is a mood disorder with ongoing feelings of sadness, hopelessness, and a lack of interest or enjoyment in activities. Depressed teens might feel down, lack energy, have changes in appetite and sleep, pull away from friends, have trouble concentrating, feel worthless or guilty, and think about self-harm. Depression can impact a teen&#x27;s emotions, behaviour, and how they function day-to-day.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Relationship between Teenage Anxiety and Depression: Teens with anxiety are more likely to get depressed, and those with depression might also feel anxious. The link between these conditions can be complicated and different for each person. They often share common causes, like genetics, environmental stress, and brain chemistry imbalances. Plus, the symptoms of anxiety and depression can feed off each other, creating a cycle of negative feelings and actions.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Therapy can help teens by giving them a safe and supportive place to talk about their thoughts, feelings, and challenges. Here are some ways therapy can help:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Emotional Support: Therapy allows teens to share their feelings and worries without judgment. They get support from a trained professional who gets what they&#x27;re going through.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Coping Skills: Therapists teach teens to handle stress, anxiety, and other challenging emotions. These skills include relaxation techniques, mindfulness, problem-solving, and good communication.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Self-Exploration and Identity Development: Therapy lets teens explore who they are, what they value, and want. It helps them understand their strengths and weaknesses, shaping a positive sense of self.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Building Resilience: Therapy helps teens develop the ability to bounce back from tough times. They learn how to face challenges, build confidence, and use healthy coping methods, giving them the strength to handle future difficulties.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Developing Healthy Relationships: Therapy supports teens in building good relationships with friends, family, and others. It focuses on improving communication, solving conflicts, and setting boundaries for healthier connections.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Managing Mental Health Conditions: For teens dealing with mental health issues like anxiety, depression, or eating disorders, therapy offers tools and strategies to manage symptoms. Therapists work with teens to create personalised treatment plans and provide ongoing support.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Academic and Personal Growth: Therapy can also help teens improve in school and personally. It helps with focus, time management, organisation, and setting goals. By addressing underlying emotional and psychological issues, therapy helps teens succeed academically and personally.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Parental Support and Family Dynamics: Therapists often include parents and caregivers in therapy, offering guidance and support to improve family dynamics. This teamwork helps enhance communication, strengthen relationships, and create a supportive environment for the teen&#x27;s growth and happiness.</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">It&#x27;s worth noting that therapy approaches can vary based on the teen&#x27;s specific needs and the therapist&#x27;s expertise. As a child psychologist Brisbane, we can confidently say that therapy offers a valuable space for teens to work through challenges, build resilience, and improve their overall mental health and well-being.</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Blushing</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Sweating</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Shaking/trembling</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>DizzinessTachycardia, rapid heartbeat</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Muscle tension</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Nausea</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Numbness or tingling in arms, hands or legs</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Diarrhoea</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Headaches</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Butterflies in the stomach</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Nail biting</span></li></ul><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Agitation/restlessness</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Pacing</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Pressured speech</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Fidgeting with ones hands</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Avoidance of feared situations or objects</span></li></ul><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Confusion</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Inability to concentrate</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Mind going blank</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Recurrent thoughts</span></li></ul></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Building a Child&#x27;s Self Esteem</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">A Child or Adolescent Clinical Psychologist can support your child in building self-esteem, giving them the confidence to believe in themselves again. Self-esteem is shaped by:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Physical appearance,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Skills,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Professional success,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>The richness of personal life.</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Self-esteem grows when we live in a way that respects and aligns with our values. But it drops when our actions clash with our values.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Low self-esteem often stems from valuing ourselves based on others&#x27; opinions rather than our own positive self-belief. Individuals with low self-esteem feel they must constantly prove themselves to gain approval, and negative feedback from others can significantly harm their self-esteem.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">High self-esteem is about liking yourself and feeling good about your achievements. It means believing you&#x27;ve achieved something for yourself, not for others&#x27; recognition. It allows for trust in your intuition, creativity, and identity building. With high self-esteem, you don&#x27;t need to win at all costs; you can be flexible and authentic. You feel safe expressing your feelings because they align with your values.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Long-term Benefits of High Self-Esteem:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Fosters a positive attitude and optimism.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Reduces anxiety and promotes healthy decision-making.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Encourages effective conflict resolution.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Helps children excel academically, in relationships, and their careers.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Builds resilience for a successful life.</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Risks of Low Self-Esteem:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Can lead to depression and anxiety.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Addressing these issues early is crucial for a healthy and confident life.</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Tips to Build Your Child&#x27;s/Adolescent&#x27;s Self-Esteem:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Belief: Show your belief in young people through positive reinforcement.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Listening: Truly listen to your children/teens to build trust.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Quality Time: Share interests and experiences with them.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Positive Attitude: Be a role model with a positive self-image.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Affection: Show them love through hugs and understanding.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Goal Setting: Support them in setting and achieving goals.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Encouragement: Motivate them to try new things and learn from failures.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Inner Wisdom: Teach them to trust their instincts and learn from experiences.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Strengths Focus: Highlight their best qualities and achievements.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Sense of Belonging: Ensure they feel loved and supported within their family/friend&#x27;s circle.</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Dreaming and Goals:</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Please encourage your child or teen to dream big and believe in their abilities. Support their dreams and their journey towards achieving them. Teach them to set SMART goals that are Specific, Measurable, Achievable, Realistic, and Time-bound, building towards their larger aspirations.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Bullying</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Bullying can severely harm a child or adolescent&#x27;s self-esteem and disrupt their identity development during adolescence.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Early detection of bullying is vital!</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Bullying is an aggressive behaviour where the victim feels powerless and vulnerable. It&#x27;s often about a bully using aggression and control to assert power. The behaviour is demeaning and disrespectful, and over time, it intensifies the power imbalance, leaving the victim feeling hurt and defenceless. Bullying can take many forms, including physical, psychological, verbal, social exclusion, and more.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">How to recognise if your child is being bullied:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Your child becomes quieter, more withdrawn, and keeps to themselves.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>They show increased anger or aggression.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>They become more sensitive to things that don&#x27;t bother them.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>They lose interest in activities they once enjoyed.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>They complain of physical ailments like stomach aches or headaches.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>They lose interest in playing with friends, doing homework, or attending school.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>They have a decreased appetite.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>They experience nightmares, bed-wetting, or poor sleep.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>They refuse to go to school.</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Ten tips to help your child deal with bullying:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Educate your children about bullying and how to recognise it.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Encourage open communication. Let them talk about both the good and evil in their lives.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Assure them that bullying is not their fault, and that seeking help is essential.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Emphasize that bullying is unacceptable and not a normal part of growing up.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Explain that bullying worsens over time, so early intervention is crucial.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Address bullies directly, not through social media.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Teach your child to be assertive. Role-play how to stand up to bullies.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Help your child identify supportive friends and practice seeking their help.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Monitor their use of computers and media. Keep computers in public areas and limit mobile phone use at night.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Be a good role model in communication and problem-solving at home.</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Taking these steps can empower your child to face and overcome bullying.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Child Anxiety</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">The following information on Childhood Anxiety will give you some insight to what Anxiety is and how it presents.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Child Psychologists can support a child or adolescent&#x27;s anxiety through therapy by teaching them to be aware of their feelings and how to work through them. Many children and adolescents who experience anxiety express that it makes them feel very uncomfortable and end up often inhibiting those parts of their life that are fundamental for them to engage in to grow their self-esteem</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Child Anxiety</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Anxiety is a common and normal emotion experienced by individuals of all ages, including children. However, when anxiety becomes persistent and intense and interferes with a child&#x27;s daily life, it may indicate the presence of a clinical condition known as child anxiety disorder. Understanding child anxiety and its symptoms is crucial for parents, caregivers, and educators to provide appropriate support and intervention.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Understanding Child Anxiety</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Child anxiety refers to excessive worry, fear, or unease that significantly impacts a child&#x27;s functioning and well-being. Anxiety disorders commonly experienced by children include generalised anxiety disorder, separation anxiety disorder, social anxiety disorder, and specific phobias. These disorders can manifest at different developmental stages and may have various causes, including genetic factors, brain chemistry, family history of anxiety, and environmental stressors.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Symptoms of Anxiety</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Child anxiety can present itself through a range of emotional, cognitive, physical, and behavioural symptoms. These may include:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Excessive worry or fear about everyday situations or events</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Restlessness, irritability, or difficulty concentrating.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Sleep disturbances, such as trouble falling asleep or frequent nightmares.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Physical symptoms like headaches, stomach-aches, or fatigue</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Avoidance of certain situations or places</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Excessive need for reassurance or seeking constant approval.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Fear of separation from parents or caregivers</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Difficulty with social interactions or performance anxiety</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Overthinking and constant anticipation of worst-case scenarios</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Supporting Children with Anxiety:</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">As a child psychologist Brisbane, we know that parents, caregivers, and educators can play a vital role in supporting children with anxiety. Here are some strategies that can be helpful:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Open Communication : Encourage children to discuss their fears and worries without judgement. Active listening and empathy can help children feel understood and supported.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Psychoeducation: Educate children about anxiety, explaining that it is a common experience and not something to be ashamed of. Provide age-appropriate information about the symptoms and coping strategies.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Establish Routines and Predictability : Create a structured and predictable environment for the child. Consistent schedules and clear expectations can help reduce anxiety triggers.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Teach Relaxation Techniques: Introduce techniques such as deep breathing, progressive muscle relaxation, or guided imagery. These techniques can help children manage their anxiety symptoms.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Gradual Exposure : If a child has specific fears or phobias, gently expose them to those situations or objects in a gradual and controlled manner. This can help them build confidence and reduce anxiety over time.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Seek Professional Help: If a child&#x27;s anxiety significantly impairs their daily functioning or causes distress, consider seeking professional help from a qualified mental health professional specialising in child anxiety disorders.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Encourage Healthy Lifestyle Habits : Promote regular physical exercise, adequate sleep, healthy eating habits, and limit exposure to stress-inducing stimuli like excessive screen time.</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Child anxiety is a natural and treatable condition that requires understanding, support, and appropriate intervention. By recognising the symptoms and implementing strategies to assist children with anxiety, parents, caregivers, and educators can provide the necessary tools and environment for children to manage and overcome their anxiety, allowing them to thrive and lead fulfilling lives. By utilising evidence-based therapies, involving parents and educators, and focusing on each child&#x27;s needs, Michelle Barratt Psychology aims to empower children with anxiety to develop practical coping skills, build resilience, and thrive in their everyday lives.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Child Depression</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Childhood depression is a severe condition marked by ongoing feelings of sadness, hopelessness, and a lack of interest or enjoyment in activities. It&#x27;s more than just the occasional moodiness or temporary sadness that kids might feel. Child depression can affect a child&#x27;s day-to-day life, their relationships, and their overall happiness.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Symptoms of child depression might include:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Constant sadness or a low mood</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Losing interest in activities they used to enjoy.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Changes in eating habits and weight (either losing or gaining weight)</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Problems with sleep, like not being able to sleep or sleeping too much.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Feeling tired or having no energy</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Trouble focusing, making decisions, or remembering things.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Feeling worthless or guilty a lot</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Thinking about death or suicide</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Pulling away from friends and family or doing worse in school</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Having physical problems, like headaches or stomach aches, with no medical reason</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Childhood depression can come from different causes, like biological factors, a family history of depression, stress from the environment, trauma, and psychological factors. It&#x27;s important to know that depression in kids might look different than in adults, and it can be harder to spot. Kids might be unable to explain how sad they feel and might show changes in their behaviour or have physical symptoms.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">If you think a child might be depressed, it&#x27;s essential to get help from a professional. Mental health experts, like the ones at Michelle Barratt Psychology, can give the proper assessment and treatment. We also have counsellors who use play therapy or other methods that help kids share their feelings and deal with their problems.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Besides therapy, support from parents, caregivers, and teachers is crucial for kids with depression. Creating a safe and caring environment, keeping open communication, and giving emotional support are vital in helping the child feel better. Working with mental health professionals can help parents understand and respond best to their child&#x27;s needs.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">We at Michelle Barratt Psychology believe that with the proper support, intervention, and a complete treatment plan, kids can learn to handle their depression, improve their well-being, and have fulfilling lives.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Child Conduct Disorder</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Please take a moment to read about Conduct Disorder (CD). Suppose your child is showing any of the behaviours described below, and you&#x27;re worried. In that case, it&#x27;s essential to get professional psychological support and treatment for your child as soon as possible. The earlier it&#x27;s treated, the better the outcome. So, don&#x27;t hesitate to book an appointment with Brisbane Clinical Psychologist Michelle Barratt at the Wynnum West or Toowong practice.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">You can make an appointment by phone, online, or via email. Check the &#x27;Appointments&#x27; tab above for available times at both practices.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Conduct Disorder (CD) is a diagnosis characterised by behaviours that are significantly more aggressive and antisocial than those seen in Oppositional Defiant Disorder (ODD). CD typically occurs in children from middle childhood to adolescence.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Children with CD exhibit behaviours that are both overt and covert, and these behaviours are more violent than those seen in ODD. Signs include:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Defiance,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Aggressiveness and destructiveness, such as destroying property,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Anger and irritability,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Widespread relationship difficulties within the family, school, and peer group, and</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Challenges in internalising social norms, such as a lack of empathy, which is often shown when children engage in: Substance use/abuse,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>High-risk taking behaviours,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Impulsive behaviours,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Promiscuity and other antisocial behaviours.</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">As child psychologists at Wynnum, we know that living with a child exhibiting these behaviours can be challenging for any family. Parents often come to their first session expressing not only deep concern but also feelings of intense frustration and helplessness.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">The negative impact on the child is also evident and distressing for their parents. The parents can see that their child struggles to regulate their emotions and seem unable to adopt the family and societal norms expected of them. Unfortunately, it&#x27;s not long before the child&#x27;s behaviour starts affecting their immediate family and peers, the school community, and the wider community, mainly because their behaviours are considerably harmful.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Negative Behaviour</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Managing negative behaviour in children and adolescents can be incredibly challenging, and when things escalate, it can be particularly draining and hard to handle. Often, this leaves parents and other family members feeling overwhelmed and uncertain about how to break the cycle of conflict and negativity.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">As a child psychologist Wynnum, we have seen children display puzzling negative behaviours, leaving parents questioning the source of such actions. Even when addressed, children may struggle to understand what they&#x27;re doing wrong or find it hard to articulate their feelings, leading to persistent negative patterns.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">This is mainly because younger children have a more challenging time expressing themselves verbally, so they often communicate through their behaviour, which can include:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Temper tantrums,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Rebellion,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Underachievement (particularly in school),</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Reluctance to interact with peers,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Delinquency,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Fighting or arguing with siblings,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Unusual silliness,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Excessive crying,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Dawdling or zoning out,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Ignoring instructions,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Shouting, screaming, and hitting other children, and</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Other forms of negative attention-seeking behaviour to express emotions they can&#x27;t otherwise articulate.</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">What Now? – There&#x27;s still hope! The key is to focus on managing the behaviour without blaming the child, which can be challenging when parents feel at a loss.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Child and Adolescent Psychology or Counselling can support and teach children how to express their negative emotions more effectively. If you&#x27;re a parent seeking a better understanding of managing difficult behaviours and negative emotions, please make an appointment for yourself and your child. We can discuss a treatment plan and how to move forward from here.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Setting Boundaries for Your Teenager</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">I would like to start with a story by psychologist and author Dr. Henry Cloud. This story illustrates the importance of preparing your child for the future through the use of boundary setting. Dr Cloud was at his friend Alison&#x27;s house when he overheard her in her 14-year-old son Cameron&#x27;s bedroom. Walking into the bedroom, Dr. Cloud asked Alison what she was doing.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Alison replied &quot;I&#x27;m cleaning up Cameron&#x27;s room. What does it look like I&#x27;m doing?&quot;</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">&quot;You are what?&quot; Dr. Cloud replied.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">&quot;I told you. I&#x27;m cleaning up his room. Why are you looking at me like that?&quot; she replied.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">&quot;I just feel sorry for Cameron&#x27;s future wife&quot; said Dr. Cloud.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">After a few moments Alison looked at Dr. Cloud and said &quot;I&#x27;ve never thought about it that way.&quot; Nor have most of us.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Dr. Cloud went on to explain that we often parent in the present without thinking about the future. But parenting has to do with more than the present, is also involves preparing your child for the future, preparing them to be responsible adults. Alison loved helping Cameron but, in many ways, her helping was not &quot;helping&quot; Cameron. He had developed a pattern in which he felt entitled to everyone else&#x27;s help. When Alison looked into the future and saw a time when Cameron would be leaving responsibilities for others to do, she became concerned and changed how she interacted with him to help him develop a sense of responsibility and to help him think about how his behaviours affected others.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Teenage years are crucial for growth, independence, and identity development. Establishing firm boundaries is critical to helping your teenager navigate this phase responsibly, teaching them that their actions have consequences and preparing them for real-world challenges.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Here are some tips for setting boundaries with your teenager:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Clarity and Reasonableness: Ensure that boundaries are communicated and agreed upon, so your teenager knows what&#x27;s expected and the consequences of crossing the line. The boundaries should be age-appropriate and consider your teenager&#x27;s ability to be responsible.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Negotiation: When setting boundaries, allow room for discussion. Your teenager might be less inclined to follow them if they&#x27;re too rigid. Let them present their arguments and consider adjusting based on their valid points. Offering choices within the boundaries can also make them feel involved in decision-making.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Respect and Empathy: Lead by example. Show respect in your interactions with your teenager and listen to their concerns. Try to understand their perspective, even if it seems trivial to you. Remember the importance of friendships, appearance, and social media in their lives.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Firmness and Consistency: It&#x27;s natural for teenagers to test limits, but it&#x27;s crucial for you as parents to enforce clear and consistent boundaries. Inconsistent or passive parenting can signal that persistent boundary-pushing will be rewarded.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Patience: Control your emotions, and don&#x27;t let your teenager&#x27;s behaviour dictate your reactions. If you&#x27;re feeling frustrated, take a break and calm down before responding. This demonstrates healthy emotional regulation.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Natural Consequences: Let your teenager face the natural outcomes of their actions. For example, if they misbehave at school, they might receive detention and miss social time. This teaches them to take responsibility for their actions.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Evolving Boundaries: As your teenager matures, adjust the boundaries to reflect their growing responsibility and trustworthiness. If they demonstrate reliable behaviour, grant them more freedom. Conversely, you may need to tighten the boundaries if they lack trustworthiness.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Enforcing Consequences: Boundaries are meaningless without consequences. Make sure the consequences are fair and relevant to the violation. Discuss the potential implications with your teenager when setting the boundary, and ensure you&#x27;re prepared to follow through.</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Setting boundaries is challenging but essential for guiding your teenager toward responsible adulthood. It&#x27;s an ongoing process, so be ready to learn from your mistakes and adapt as needed. Establishing clear boundaries and consequences will help your teenager understand expectations and maintain discipline without harming your relationship.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Surviving Your Parents</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Navigating the teenage years can be like riding a rollercoaster – thrilling but also full of ups and downs. As you grow into your person, it&#x27;s natural to find yourself clashing with your parents more often. It&#x27;s a time of change, not just for you but for your whole family. Here are some tips to help you get through this journey with your parents:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Communication is Key: Open and honest communication is crucial. Share your thoughts and feelings with your parents. It&#x27;s okay to express your need for more independence but try to do so respectfully. Remember, they&#x27;re adjusting to this new phase, too.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Pick Your Battles: Not every disagreement needs to turn into a full-blown argument. Sometimes, letting the small stuff slide is worth keeping the peace.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Empathy Works Both Ways: Just as you want your parents to understand you, try to see things from their perspective, too. They care about you and want what&#x27;s best for you, even if it doesn&#x27;t always feel that way.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Set Boundaries : It&#x27;s healthy to set boundaries. Discuss your need for privacy and space with your parents. Finding a balance between your independence and their concerns is vital.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Seek Support: If you&#x27;re having trouble communicating with your parents, it might be helpful to talk to someone outside the situation, like a trusted family member, teacher, or counsellor.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Be Patient: This phase of life is temporary. As you and your parents navigate these changes, there will be good and challenging days. Be patient with yourself and with them.</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Remember, surviving your parents during your teenage years is about balancing asserting your independence and respecting their role. With open communication, empathy, and patience, you can strengthen your relationship with your parents during this time of growth and change.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Surviving Your Teenager</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">How Does It Feel?</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">You might notice that your teenager has changed drastically—once you&#x27;re an adorable child, you find yourself asking, &quot;Who are you?&quot; These moments can be confusing and painful for parents. Teenagers are undergoing the &#x27;individualised process,&#x27; also known as the &#x27;push-pull&#x27; analogy—sometimes they love you, and occasionally they don&#x27;t.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Teenagers are navigating a journey to become the person they want to be, which might differ from what you envisioned. For parents, this journey can feel like walking through a minefield.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Don&#x27;t fear your teenager&#x27;s potential. If you&#x27;re unsure, watch some videos below for support. Remember, with the right attitude and outlook, anything is possible. However, commitment to change is necessary.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Parenting Support</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">If you&#x27;re at a loss for words and your child&#x27;s behaviour is foreign to you, it might be time to seek parenting support. You can:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Book an appointment with a psychologist to guide you through the following steps.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Consult your GP if you&#x27;re experiencing anxiety or depression symptoms and ask for a referral. Remember to inquire about a Mental Health Plan if needed.</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Different Parents Make the World Go Round</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Families come in various forms:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Biological/Nuclear Families: Parents and their biological or adopted children.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Stepfamilies: Parents with children from previous relationships.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Blended Families: Parents with children from previous relationships and a child together.</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Each family type faces challenges, such as differing parenting styles, scheduling conflicts, and navigating relationships in blended or stepfamilies.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">What My Teenager Can Be Like?</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Your teenager might:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Spend most of their time in their room,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Be more rude than respectful,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Seem like they don&#x27;t understand anything,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Get angry and frustrated quickly,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Refuse to do chores,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Stay up late and sleep in,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Ignore boundaries,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Have communication breakdowns,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Show little family participation,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Take advantage of situations,</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Defy trust.</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Parenting can feel overwhelming even if your teenager doesn&#x27;t exhibit all these behaviours. It&#x27;s crucial that they feel supported and connected to you.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Survival Parenting Tips</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Maintaining communication is vital. Some tips:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Talk to your children but make final decisions as an adult.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Encourage responsibility and commitment in their decisions.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Have regular one-on-one time to discuss their lives.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Set boundaries to instil trust, respect, and understanding.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Focus on current issues rather than dwelling on the past.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Collaborate with your teenager to solve problems and plan for the future.</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">This is just the beginning. If you&#x27;d like more guidance on navigating your teenager&#x27;s development, consider booking an appointment with Michelle Barratt.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">As child psychologists at Wynnum, Michelle Barratt Psychology prioritises providing a therapeutic environment based on confidentiality, trust, and empathy. She believes in respecting the client&#x27;s perspective and supporting their journey to change. When dealing with mental health or trauma, emotions like self-blame and low self-esteem can cloud perception. Therapy can help clear this fog.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Toddler Tantrums</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">When your child has a temper tantrum, it can be challenging to deal with, especially during something routine like your weekly grocery shop. It&#x27;s particularly difficult when your child&#x27;s meltdown seems to be over something trivial, like not buying them a toy truck.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Dealing with the aftermath of setting boundaries and saying &quot;No&quot; can be even more challenging, as efforts to stop the tantrum may seem to make things worse. You might find yourself at a loss as your child lies on the floor, kicking and screaming, drawing unwanted attention from onlookers.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">For most parents in this situation, the main goal is to calm the child down to continue with their day, ideally without the judgmental stares and comments from others.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">What It Can Look Like and Feel Like – As a Parent</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Public temper tantrums can trigger feelings of shame, failure, and inadequacy, often stemming from thoughts of being a &quot;bad parent.&quot; You might worry about being judged negatively by onlookers. However, it&#x27;s worth noting that many people, especially those with children, are likely to sympathise rather than judge.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">When efforts to calm your child escalate the tantrum, you&#x27;re faced with a dilemma:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Relent: Giving in and buying the toy might work in the short term but negatively reinforces the behaviour in the long term.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Punish: Attempt to regain control by shouting or threatening to smack your child.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Abandon shopping mission: Drag your child out of the store, effectively letting them win and reinforcing the behaviour.</span></li><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Freeze: Do nothing, feeling stuck in the situation.</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">These responses are often ineffective and are part of our innate survival mechanisms (Fight, Flight, or Freeze). When triggered, it&#x27;s hard to attune to our child&#x27;s needs and identify the underlying cause of the tantrum.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Children don&#x27;t come with a manual, so we must learn how to read and fulfil their needs. During a tantrum, children need help organising their feelings. They require a bigger, stronger, wiser, and kinder parent – someone who can take charge without being too weak or harsh.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">If you&#x27;re struggling with your child&#x27;s temper tantrums or managing your emotions, consider speaking to a psychologist for support. Psychological therapy can be beneficial in understanding and managing tantrums, allowing you to enjoy your time with your child and address the underlying issues causing the negative behaviour.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Please be advised that you&#x27;ll receive a response within 24 to 48 hours.</p></div></section><section class="bg-lilac !py-14"><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><p class="text-[12px] font-semibold uppercase tracking-[0.2em] text-rose mb-4">More in <!-- -->Children &amp; Adolescents</p><ul class="flex flex-wrap gap-3"><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/adolescent-anxiety-depression">Adolescent Anxiety &amp; Depression<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/child-anxiety">Child Anxiety<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li></ul></div></section><section class="bg-blush"><div class="mx-auto max-w-4xl px-5 py-14 md:py-16 text-center"><p class="text-[12px] font-semibold uppercase tracking-[0.2em] text-rose mb-2.5">Take the first step</p><h2 class="text-[30px] md:text-[40px] font-semibold leading-[1.1]">Ready to Take the First Step?</h2><div class="h-[3px] w-14 bg-sun mt-4 mx-auto" aria-hidden="true"></div><p class="mt-5 text-[17px]">Seeking support can feel overwhelming, but you do not have to navigate life&#x27;s challenges alone. Our administration team can help answer your questions, explain appointment options and connect you with a suitable practitioner.</p><p class="mt-3">Prefer to call? Phone our administration team on <a class="text-ocean underline underline-offset-4 font-medium" href="tel:0731850040">07 3185 0040</a>.</p><div class="mt-7 flex flex-wrap justify-center gap-3"><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 bg-rose text-white hover:bg-[#9d2a59] " href="/practitioners">Book Online</a><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 bg-ocean text-white hover:bg-[#095a6f] " href="/contact">Contact Us</a><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 border border-plum text-plum hover:bg-lilac  active" href="/therapy-services" data-status="active" aria-current="page">Explore Services</a></div><p class="mt-5 text-sm text-ink/70">If in crisis, please call 000.</p></div></section><!--/$-->`,r={title:e,description:t,html:n};export{r as default,t as description,n as html,e as title};